int ufd = userfaultfd(O_CLOEXEC | UFFD_SHARED_FORK);

// --- 1. Negotiation (op = UFFDIO_API) ---
struct uffdio_api api = {
    .api = UFFD_API_VERSION,
    .features = 0, // Request all features
};

// Check for EFAULT, EINVAL
ioctl(ufd, UFFDIO_API, &api);


// --- 2. Registration (op = UFFDIO_REGISTER) ---
void *area = mmap(...);
size_t size = 0x10000;

struct uffdio_register reg = {
    .range = { .start = (unsigned long)area, .len = size },
    .mode = UFFDIO_REGISTER_MODE_MISSING,
};

// Check for EFAULT, ENOMEM, EPERM
ioctl(ufd, UFFDIO_REGISTER, &reg);

// reg.ioctls now holds supported operations for the range
// (e.g., UFFDIO_COPY, UFFDIO_ZEROPAGE)
munmap(area, size);
close(ufd);
